"""Shared rectangle and serialized solver result types."""

from dataclasses import dataclass

@dataclass(frozen=True)
class Rect:
    row: int
    col: int
    height: int
    width: int

    @property
    def area(self) -> int:
        return self.height * self.width

shikaku/validation.py:
"""Independent witness validation."""

from .model import Rect


def validate_partition(n: int, rects: list[Rect]) -> int:
    """Independent cell-based witness check; returns the distinct-area count."""
    if n < 1:
        raise ValueError("n must be positive")
    occupied: set[tuple[int, int]] = set()
    for r in rects:
        if (r.row < 0 or r.col < 0 or r.height < 1 or r.width < 1
                or r.row + r.height > n or r.col + r.width > n):
            raise ValueError("rectangle outside grid or non-positive dimensions")
        for row in range(r.row, r.row + r.height):
            for col in range(r.col, r.col + r.width):
                cell = row, col
                if cell in occupied:
                    raise ValueError("overlapping rectangles")
                occupied.add(cell)
    if len(occupied) != n * n:
        raise ValueError("partition has uncovered cells")
    return len({r.area for r in rects})

tests/oracle.py:
"""Independent cell-mask exhaustive oracle for small grids."""

def cell_oracle(n: int) -> tuple[int, int]:
    """Enumerate all partitions: no skyline, area bound, seed, or memoization.

    Branch on the LAST free cell, and try all rectangles containing that cell.
    """
    candidates = [[] for _ in range(n * n)]
    for top in range(n):
        for bottom in range(top + 1, n + 1):
            for left in range(n):
                for right in range(left + 1, n + 1):
                    cells = [r * n + c for r in range(top, bottom)
                             for c in range(left, right)]
                    mask = sum(1 << c for c in cells)
                    for c in cells:
                        candidates[c].append((mask, len(cells)))
    full = (1 << (n * n)) - 1
    best = leaves = 0

    def visit(occupied: int, used: frozenset[int]) -> None:
        nonlocal best, leaves
        if occupied == full:
            best = max(best, len(used))
            leaves += 1
            return
        cell = (full ^ occupied).bit_length() - 1
        for mask, area in candidates[cell]:
            if not mask & occupied:
                visit(occupied | mask, used | {area})

    visit(0, frozenset())
    return best, leaves

tests/test_constructions_improved.py:
"""Independently check coverage and the proved counts of new witnesses."""

import unittest

from shikaku.constructions import initial_partition
from shikaku.improved_constructions import (
    best_partition, partition_11_over_8, residual_partition,
)
from shikaku.validation import validate_partition


class ImprovedConstructionTests(unittest.TestCase):
    def test_all_cells_and_theorem_count(self):
        for t in range(1, 17):
            n = 16*t
            self.assertEqual(validate_partition(n, partition_11_over_8(n)), 22*t-1)

    def test_every_padding_remainder(self):
        for n in range(16, 64):
            self.assertGreaterEqual(validate_partition(n, partition_11_over_8(n)),
                                    22*(n//16)-1)

    def test_residual_two_rows(self):
        for n in range(1, 65):
            old = validate_partition(n, initial_partition(n))
            new = validate_partition(n, residual_partition(n))
            self.assertEqual(new, old + (n % 6 in (0, 5)))

    def test_best_and_known_exact_cases(self):
        for n in range(1, 81):
            score = validate_partition(n, best_partition(n))
            self.assertGreaterEqual(score, validate_partition(n, initial_partition(n)))
        for n, expected in [(5, 6), (6, 7), (16, 21), (17, 23), (20, 27)]:
            self.assertEqual(validate_partition(n, best_partition(n)), expected)

    def test_invalid_dimensions(self):
        for function in (best_partition, residual_partition, partition_11_over_8):
            for n in (0, -1, 1.5, True):
                with self.assertRaises(ValueError):
                    function(n)
        with self.assertRaises(ValueError):
            partition_11_over_8(15)


if __name__ == '__main__':
    unittest.main()

tests/test_correctness.py:
"""Cross-check skyline search against independent full enumeration."""

import unittest
from shikaku import Rect, solve, validate_partition
from shikaku.constructions import initial_partition
from tests.oracle import cell_oracle


class BaselineTests(unittest.TestCase):
    def test_cross_check_all_partitions(self):
        for n in range(1, 5):
            with self.subTest(n=n):
                expected, leaves = cell_oracle(n)
                for prune in (False, True):
                    result = solve(n, prune=prune)
                    self.assertEqual(result["status"], "OPTIMAL")
                    self.assertEqual(result["k"], expected)
                    self.assertEqual(validate_partition(n, [Rect(**r) for r in
                                                           result["rectangles"]]), expected)
                    if not prune:
                        self.assertEqual(result["complete_partitions"], leaves)

    def test_note_exact_values(self):
        for n, expected in [(7, 9), (8, 10), (13, 17)]:
            result = solve(n)
            self.assertEqual(result["k"], expected)

    def test_construction(self):
        for n in range(1, 41):
            score = validate_partition(n, initial_partition(n))
            self.assertGreaterEqual(score, n + 2 * (((n + 1) // 2 - 1) // 3))

    def test_timeout_is_not_infeasibility(self):
        result = solve(5, time_limit=0)
        self.assertEqual(result["status"], "TIME_LIMIT")
        self.assertIsNone(result["k"])
        self.assertLess(result["lower_bound"], result["upper_bound"])
        validate_partition(5, [Rect(**r) for r in result["rectangles"]])

    def test_invalid_input(self):
        for n in (0, -1, 1.5, True):
            with self.assertRaises(ValueError):
                solve(n)
        for limit in (-1, float("nan"), float("inf")):
            with self.assertRaises(ValueError):
                solve(2, time_limit=limit)


if __name__ == "__main__":
    unittest.main()

tests/test_strips.py:
"""Validate strip witnesses and prevent restricted certificates becoming global."""

import importlib.util
import unittest

from shikaku import Rect, validate_partition
from shikaku.solvers.strips import solve, width_partitions


HAS_ORTOOLS = importlib.util.find_spec("ortools") is not None


def strip_oracle(n):
    """Independent exhaustive DP from every ordered composition of each strip."""
    configs = []
    for height in range(1, n + 1):
        for cuts in range(1 << (n - 1)):
            widths = []
            last = 0
            for col in range(1, n):
                if cuts & (1 << (col - 1)):
                    widths.append(col - last)
                    last = col
            widths.append(n - last)
            configs.append((height, frozenset(height * w for w in widths)))
    states = [{frozenset()}] + [set() for _ in range(n)]
    for row in range(n):
        for areas in states[row]:
            for height, added in configs:
                if row + height <= n:
                    states[row + height].add(areas | added)
    return max(map(len, states[n]))


class StripTests(unittest.TestCase):
    def test_partitions(self):
        expected = {(5,), (1, 4), (2, 3), (1, 1, 3), (1, 2, 2)}
        self.assertEqual(set(width_partitions(5, 3)), expected)

    def test_zero_time_preserves_witness(self):
        result = solve(5, time_limit=0)
        self.assertEqual(result["status"], "TIME_LIMIT")
        self.assertIsNone(result["k"])
        self.assertEqual(result["restricted_status"], "NOT_RUN")
        self.assertEqual(validate_partition(5, [Rect(**r) for r in result["rectangles"]]),
                         result["lower_bound"])

    @unittest.skipUnless(HAS_ORTOOLS, "optional OR-Tools dependency not installed")
    def test_independent_small_strip_enumeration(self):
        for n in range(1, 5):
            result = solve(n, max_parts=n, time_limit=10)
            self.assertEqual(result["lower_bound"], strip_oracle(n))
            self.assertEqual(validate_partition(n, [Rect(**r) for r in result["rectangles"]]),
                             result["lower_bound"])

    @unittest.skipUnless(HAS_ORTOOLS, "optional OR-Tools dependency not installed")
    def test_restricted_optimum_is_not_global(self):
        result = solve(5, max_parts=1, time_limit=10)
        self.assertEqual(result["restricted_status"], "OPTIMAL")
        self.assertEqual(result["status"], "LOWER_BOUND")
        self.assertIsNone(result["k"])
        self.assertLess(result["lower_bound"], result["upper_bound"])
        self.assertEqual(result["lower_bound"], result["initial_lower_bound"])

    @unittest.skipUnless(HAS_ORTOOLS, "optional OR-Tools dependency not installed")
    def test_better_witness_certifies_exactness(self):
        result = solve(5, time_limit=10)
        self.assertEqual(result["k"], 6)
        self.assertGreater(result["lower_bound"], result["initial_lower_bound"])

    def test_invalid_options(self):
        for n in [0, -1, 2.5, True]:
            with self.assertRaises(ValueError):
                solve(n)
        for kwargs in [{"max_parts": 0}, {"max_height": -1}, {"workers": 0},
                       {"seed": -1}, {"time_limit": float("nan")},
                       {"time_limit": -1}]:
            with self.assertRaises(ValueError):
                solve(5, **kwargs)


if __name__ == "__main__":
    unittest.main()

